:root {
  --bg: #ffffff; --stage-bg: #eef0f3; --text: #1b1d21; --muted: #5b616c; --border: #d9dce1; --surface: #f5f6f8;
  --accent: #2c5bc9; --train: #2c5bc9; --val: #d9730d; --warm-text: #b35c00; --grid: #e6e8ec; --cell: #ffffff;
  --bar-u: #c3c8d0; --bar-s: #6b7280; --bar-k: #2c5bc9; --ref: #8a909a;
  --hl-bg: #fff0b8; --hl-text: #1b1d21;
  --font: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #17191d; --stage-bg: #0e0f12; --text: #e8eaee; --muted: #a3a9b4; --border: #3a3e46; --surface: #22252b;
    --accent: #8db0ff; --train: #7ea6ff; --val: #ffa65a; --warm-text: #ffa65a; --grid: #2c3037; --cell: #17191d;
    --bar-u: #4a4f58; --bar-s: #9aa1ad; --bar-k: #6f98f5; --ref: #8a909a;
    --hl-bg: #4d3f0a; --hl-text: #ffe9a3;
  }
}
:root[data-theme="dark"] {
  --bg: #17191d; --stage-bg: #0e0f12; --text: #e8eaee; --muted: #a3a9b4; --border: #3a3e46; --surface: #22252b;
  --accent: #8db0ff; --train: #7ea6ff; --val: #ffa65a; --warm-text: #ffa65a; --grid: #2c3037; --cell: #17191d;
  --bar-u: #4a4f58; --bar-s: #9aa1ad; --bar-k: #6f98f5; --ref: #8a909a;
  --hl-bg: #4d3f0a; --hl-text: #ffe9a3;
}
* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; }
body { background: var(--stage-bg); color: var(--text); overflow: hidden; font-family: var(--font); }
#viewport { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; }
#stage { width: 1280px; height: 720px; position: relative; flex: none; transform-origin: center center; }
.slide { position: absolute; inset: 0; background: var(--bg); padding: 26px 60px 44px; display: none;
  flex-direction: column; font-size: 23px; line-height: 1.4; border-radius: 4px; overflow: hidden; }
.slide.active { display: flex; }
.strip { display: flex; gap: 8px; align-items: center; font-size: 13px; font-weight: 600; letter-spacing: 0.8px;
  text-transform: uppercase; color: var(--muted); margin-bottom: 14px; opacity: 0.85; }
.strip span.on { color: var(--accent); opacity: 1; }
.strip span.on::before { content: ""; display: inline-block; width: 7px; height: 7px; border-radius: 50%;
  background: var(--accent); margin-right: 6px; vertical-align: 1px; }
.strip i { font-style: normal; opacity: 0.5; }
h1 { font-size: 48px; line-height: 1.14; margin: 0 0 16px; letter-spacing: -0.6px; font-weight: 700; }
h2 { font-size: 31px; line-height: 1.2; margin: 0 0 20px; letter-spacing: -0.3px; font-weight: 700; }
p { margin: 0 0 12px; }
ul, ol { margin: 0; padding-left: 26px; }
li { margin-bottom: 8px; }
b { font-weight: 650; }
.key { color: var(--accent); }
.lead { font-size: 22px; color: var(--muted); }
.foot { font-size: 16px; color: var(--muted); margin: auto 0 0; padding-top: 10px; line-height: 1.35; }
.cols { display: flex; gap: 28px; flex: 1; min-height: 0; }
.cols > div { flex: 1; min-width: 0; }
.cards3, .cards4 { display: grid; gap: 18px; }
.cards3 { grid-template-columns: repeat(3, 1fr); }
.cards4 { grid-template-columns: repeat(4, 1fr); }
.card { background: var(--surface); border: 1px solid var(--border); border-radius: 10px; padding: 16px 20px; }
.card h3 { font-size: 22px; margin: 0 0 6px; color: var(--text); }
table { border-collapse: collapse; width: 100%; font-size: 20px; font-variant-numeric: tabular-nums; }
th, td { padding: 7px 10px; border-bottom: 1px solid var(--border); text-align: left; vertical-align: top; }
th { color: var(--muted); font-weight: 600; font-size: 17px; }
td.n, th.n { text-align: right; white-space: nowrap; }
tr.sep td { border-top: 2px solid var(--border); }
table.roomy { font-size: 22px; } table.roomy th, table.roomy td { padding: 9px 10px; }
.title-slide { justify-content: center; }
.title-slide .strip { position: absolute; top: 26px; left: 60px; }
.title-slide .kicker { font-size: 18px; color: var(--accent); font-weight: 600; letter-spacing: 1px; text-transform: uppercase; margin-bottom: 8px; }
.title-slide .sub { font-size: 26px; color: var(--muted); margin-bottom: 40px; }
.title-slide .foot { position: absolute; left: 60px; bottom: 40px; }
svg text { fill: var(--text); font-family: var(--font); }
svg .mut { fill: var(--muted); }
svg .ax { stroke: var(--muted); stroke-width: 1.2; fill: none; }
svg .gl { stroke: var(--grid); stroke-width: 1; }
svg .bar-u { fill: var(--bar-u); } svg .bar-s { fill: var(--bar-s); } svg .bar-k { fill: var(--bar-k); }
svg .bar-va { fill: var(--val); }
.notes { display: none; position: absolute; left: 0; right: 0; bottom: 0; z-index: 5; background: var(--surface);
  border-top: 3px solid var(--accent); padding: 14px 60px 22px; font-size: 20px; line-height: 1.45; color: var(--text); }
.notes::before { content: "Speaker notes"; display: block; font-size: 13px; font-weight: 600; letter-spacing: 0.8px;
  text-transform: uppercase; color: var(--muted); margin-bottom: 4px; }
body.show-notes .slide.active .notes { display: block; }
#ui { position: fixed; top: 12px; right: 14px; z-index: 10; display: flex; gap: 8px; }
#ui button { font: 600 15px var(--font); color: var(--text); background: var(--bg); border: 1px solid var(--border);
  border-radius: 8px; padding: 7px 12px; cursor: pointer; }
#ui button:hover { border-color: var(--accent); }
#counter { position: absolute; right: 24px; bottom: 14px; font-size: 16px; color: var(--muted); z-index: 3;
  font-variant-numeric: tabular-nums; }
#progress { position: absolute; left: 0; bottom: 0; height: 4px; background: var(--accent); z-index: 3; transition: width 0.2s ease; }
@media print {
  @page { size: 1280px 720px; margin: 0; }
  html, body { height: auto; overflow: visible; background: var(--bg); }
  * { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  #ui, #counter, #progress, .notes { display: none !important; }
  #viewport { position: static; display: block; }
  #stage { transform: none !important; width: 1280px; height: auto; }
  .slide { display: flex !important; position: relative; inset: auto; width: 1280px; height: 720px; border-radius: 0;
    break-after: page; page-break-after: always; }
  .slide:last-of-type { break-after: auto; page-break-after: auto; }
}

.hl { background: var(--hl-bg); color: var(--hl-text); font-weight: 700; border-radius: 5px; padding: 0 6px;
  box-decoration-break: clone; -webkit-box-decoration-break: clone; }
.lab { display: block; font-size: 13px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase;
  color: var(--accent); margin-bottom: 4px; }
.lab.warm { color: var(--warm-text); }
.num { font-size: 60px; font-weight: 700; line-height: 1.15; letter-spacing: -1.2px; font-variant-numeric: tabular-nums;
  white-space: nowrap; margin: 2px 0 8px; color: var(--text); }
.num.k { color: var(--accent); } .num.w { color: var(--warm-text); }
.tile { display: flex; flex-direction: column; padding: 18px 20px 16px; }
.tile h3 { font-size: 23px; margin: 0; }
.tile .txt { font-size: 19px; line-height: 1.4; color: var(--muted); margin: 0; }
.meter { height: 8px; border-radius: 4px; background: var(--grid); overflow: hidden; margin: 0 0 10px; }
.meter i { display: block; height: 100%; border-radius: 4px; background: var(--bar-s); }
.statcard { border-left: 5px solid var(--accent); display: flex; flex-direction: column; justify-content: center; padding: 22px 26px; }
.statcard .big { font-size: 21px; line-height: 1.4; margin: 0 0 12px; }
.statcard .small { font-size: 18px; line-height: 1.45; color: var(--muted); margin: 0; }
.stack { display: flex; flex-direction: column; gap: 14px; }
.stack .card { flex: 1; display: flex; flex-direction: column; justify-content: center; padding: 16px 24px; }
.stack .card p { font-size: 22px; color: var(--muted); margin: 0; }
.stack .card h3 { color: var(--accent); font-size: 24px; }
.note { font-size: 21px; line-height: 1.45; color: var(--muted); margin: 14px 0 0; }
.badge { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase;
  background: var(--hl-bg); color: var(--hl-text); border: 1px solid var(--val); border-radius: 999px;
  padding: 1px 8px; margin: 0 8px 0 0; vertical-align: 3px; }
table.grid { font-size: 27px; } table.grid th { font-size: 19px; } table.grid td, table.grid th { padding: 15px 14px; }
table.grid td.n { width: 190px; font-weight: 650; }
table.grid tr.refrow td { background: var(--surface); color: var(--muted); font-weight: 400; border-top: 2px solid var(--border); }
table.att { font-size: 21px; } table.att th { font-size: 16px; } table.att td, table.att th { padding: 9px 8px; }
table.att td:first-child { font-weight: 650; white-space: nowrap; }
.sub2 { display: flex; gap: 28px; margin-top: 26px; }
.sub2 > div { flex: 1; min-width: 0; }
.sub2 h3 { font-size: 22px; margin: 0 0 4px; color: var(--accent); }
.sub2 p { font-size: 21px; color: var(--muted); margin: 0; }
ol.plan { font-size: 27px; padding: 16px 0 0 34px; margin-top: 0; border-top: 1px solid var(--border); } ol.plan li { margin-bottom: 22px; }
.dec { border-top: 1px solid var(--border); padding: 16px 0 18px; }
.dec h3 { font-size: 25px; margin: 0 0 3px; }
.dec p { font-size: 22px; line-height: 1.4; color: var(--muted); margin: 0; }
.mid { margin-top: auto; margin-bottom: 0; }
.t3 .num { font-size: 68px; } .t3 .txt { font-size: 23px; } .t3 .tile { padding: 24px 26px; }
.t5 .num { font-size: 72px; } .t5 .txt { font-size: 21px; } .t5 .tile h3 { font-size: 25px; } .t5 .tile { padding: 22px 22px 20px; }
.t9 .num { font-size: 64px; } .t9 .txt { font-size: 21px; } .t9 .tile { padding: 22px 22px 20px; } .t9 .lab { font-size: 14px; }
table.reg { font-size: 24px; } table.reg th, table.reg td { padding: 12px 10px; } table.reg th { font-size: 18px; }
.author { font-size: 24px; margin: 0; } .author span { color: var(--muted); font-size: 20px; }
svg .chance-bg { stroke: var(--bg); stroke-width: 5; }
svg .chance { stroke: var(--text); stroke-width: 1.8; stroke-dasharray: 6 5; }
svg .v { font-weight: 700; paint-order: stroke; stroke: var(--bg); stroke-width: 6px; stroke-linejoin: round; }
svg .hatch-bg { fill: var(--bar-u); } svg .hatch-ln { stroke: var(--bar-s); stroke-width: 2; }
svg .vin { fill: var(--bg); font-weight: 700; }
svg .hatch-box { stroke: var(--bar-s); stroke-width: 1.2; }
svg .bx { fill: var(--surface); stroke: var(--border); stroke-width: 1.5; }
svg .bx-k { fill: var(--surface); stroke: var(--accent); stroke-width: 2; }
svg .bx-w { fill: var(--surface); stroke: var(--val); stroke-width: 3; }
svg .bx-d { fill: none; stroke: var(--muted); stroke-width: 1.8; stroke-dasharray: 6 4; }
svg .arr { stroke: var(--muted); stroke-width: 2; fill: none; }
svg .arr-d { stroke: var(--muted); stroke-width: 2; fill: none; stroke-dasharray: 6 4; }
svg .dot { stroke: var(--muted); stroke-width: 1.5; stroke-dasharray: 2 4; }
svg .ahp { fill: var(--muted); }
.callout { background: var(--surface); border: 1px solid var(--border); border-left: 5px solid var(--accent);
  border-radius: 8px; padding: 16px 22px; font-size: 26px; line-height: 1.4; margin-top: 8px; }
.na { border: 2px dashed var(--border); border-radius: 10px; padding: 26px 30px; font-size: 23px; color: var(--muted); }
.na b { color: var(--text); }
table.atk { font-size: 19px; } table.atk td { padding: 9px 8px; } table.atk td:first-child { font-weight: 650; white-space: nowrap; }
.qs .card { padding: 22px 24px; } .qs .card h3 { font-size: 24px; color: var(--accent); margin-bottom: 8px; } .qs .card p { font-size: 22px; color: var(--muted); margin: 0; }
.t6 .tile { padding: 18px 22px; } .t6 .num { font-size: 44px; margin: 0 0 6px; } .t6 .txt { font-size: 20px; }
table.reg2 { font-size: 19px; } table.reg2 th { font-size: 15px; } table.reg2 th, table.reg2 td { padding: 5px 10px; }
.dets { font-size: 18px; color: var(--muted); margin: 12px 0 14px; line-height: 1.5; } .dets b { color: var(--accent); }
.ev .card { padding: 14px 18px; } .ev .card h3 { font-size: 21px; color: var(--accent); } .ev .card p { font-size: 19px; color: var(--muted); margin: 0; line-height: 1.4; }
.disc ul { font-size: 19px; line-height: 1.4; padding-left: 22px; } .disc li { margin-bottom: 10px; } .disc svg { margin-top: 8px; }
ol.take { font-size: 25px; line-height: 1.4; padding-left: 34px; margin-top: 6px; } ol.take li { margin-bottom: 20px; padding-left: 6px; }
.t15 .tile { padding: 14px 18px 12px; } .t15 .num { font-size: 42px; margin: 0 0 6px; } .t15 .txt { font-size: 17px; line-height: 1.35; }
.sm ol.plan { font-size: 20px; padding: 10px 0 0 28px; } .sm ol.plan li { margin-bottom: 8px; }
.sm .dec { padding: 8px 0 9px; } .sm .dec h3 { font-size: 20px; margin: 0; } .sm .dec p { font-size: 18px; }
.refs { columns: 2; column-gap: 44px; font-size: 17px; line-height: 1.4; padding-left: 30px; margin: 0; } .refs li { margin-bottom: 16px; break-inside: avoid; padding-left: 4px; }
.prop { gap: 18px; } .prop > .card { flex: 0 0 524px; padding: 12px 20px 6px; } .prop .stack { gap: 12px; } .prop .stack .card { padding: 10px 20px 6px; flex: 1; justify-content: flex-start; }
.prop .card h3 { font-size: 20px; color: var(--accent); margin: 0 0 6px; } .prop .card p { font-size: 16px; line-height: 1.38; margin: 0 0 6px; color: var(--muted); } .prop .card p b { color: var(--text); }
.prop .stack .card p { font-size: 15.5px; margin-bottom: 4px; }
.callout.takes { font-size: 17px; padding: 8px 18px; margin-top: 12px; }
svg .mk { fill: var(--bg); stroke: var(--val); stroke-width: 2.5; }
table.relc { font-size: 19px; } table.relc td, table.relc th { padding: 9px 8px; }
table.rel { font-size: 15px; table-layout: fixed; } table.rel th { font-size: 14px; } table.rel td, table.rel th { padding: 4px 8px; line-height: 1.3; }
table.rel td:first-child { font-weight: 650; } table.rel th:first-child { width: 200px; } table.relc th:first-child { width: 250px; } table.rel tr.grp td { font-size: 13px; font-weight: 700; letter-spacing: 0.8px; text-transform: uppercase; color: var(--accent); padding-top: 7px; border-bottom: 2px solid var(--border); }
table.rel.rel3 th:first-child { width: 250px; }
table.pairs { font-size: 16px; margin-top: 6px; } table.pairs th { font-size: 15px; } table.pairs td, table.pairs th { padding: 5px 8px; white-space: nowrap; } table.pairs td:last-child { white-space: normal; } table.pairs td:first-child { font-weight: 650; }
svg .pl { fill: var(--bg); stroke: var(--text); stroke-width: 2; } svg .mkf { fill: var(--val); stroke: var(--val); stroke-width: 1.5; }
.qbig .card { padding: 30px 28px; } .qbig .card h3 { font-size: 27px; margin-bottom: 12px; } .qbig .card p { font-size: 24px; line-height: 1.45; }
.slide .callout:not(.takes) { font-size: 28px; padding: 22px 26px; }
table.mdl th { font-size: 16px !important; }
table.inp { font-size: 17px !important; } table.inp td, table.inp th { padding: 4px 8px !important; }
.ev .card { padding: 11px 16px !important; } .ev .card p { font-size: 17px !important; } .ev .card h3 { font-size: 20px !important; }
.prop .card p, .prop .stack .card p { font-size: 17px !important; }
table.grid td, table.grid th { padding: 11px 14px !important; }
ol.take { font-size: 23px !important; }
.cap { font-size: 16px; color: var(--muted); margin: 4px 0 0; line-height: 1.35; }
svg .dot2 { stroke: var(--muted); stroke-width: 2; stroke-dasharray: 2 3; }
table.rel18 { font-size: 18px; } table.rel18 th { font-size: 16px; } table.rel18 td, table.rel18 th { padding: 8px 8px; line-height: 1.32; } table.rel18 tr.grp td { font-size: 14px; }
table.inp { font-size: 18px; margin-top: 12px; } table.inp th { font-size: 16px; } table.inp td, table.inp th { padding: 7px 8px; line-height: 1.3; } table.inp td:first-child { font-weight: 650; white-space: nowrap; }
table.mdl { font-size: 16px; margin-bottom: 12px; } table.mdl th { font-size: 15px; } table.mdl td, table.mdl th { padding: 7px 5px; white-space: nowrap; } table.mdl td:first-child { font-weight: 650; }
.slide > svg { flex: none; }
table.mdl tr.refrow td { background: var(--surface); color: var(--muted); font-weight: 400; }
table.rel.relc { font-size: 17px; } table.rel.relc th { font-size: 16px; } table.rel.relc td, table.rel.relc th { padding: 6px 8px; }
.t15 .lab { font-size: 16px; } .t15 .num { white-space: nowrap; }

:root { --oc: #2c5bc9; --ul: #d9730d; --sup: #6b7280; --s0: #2c5bc9; --s1: #d9730d; --s2: #1f8a5b; --s3: #8a4bbf; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { --oc: #8db0ff; --ul: #ffa65a; --sup: #9aa1ad;
  --s0: #8db0ff; --s1: #ffa65a; --s2: #5fd39a; --s3: #c99ae6; } }
:root[data-theme="dark"] { --oc: #8db0ff; --ul: #ffa65a; --sup: #9aa1ad; --s0: #8db0ff; --s1: #ffa65a; --s2: #5fd39a; --s3: #c99ae6; }
svg .c-oc { fill: var(--oc); } svg .c-ul { fill: var(--ul); } svg .c-sup { fill: var(--sup); }
svg .l-oc { stroke: var(--oc); } svg .l-ul { stroke: var(--ul); } svg .l-sup { stroke: var(--sup); }
svg .sd0 { fill: var(--bg); stroke: var(--text); stroke-width: 1.8; } svg .sdx { fill: var(--text); stroke: var(--bg); stroke-width: 1; }
svg .eb { stroke: var(--text); stroke-width: 2; }
svg .len { stroke: var(--text); stroke-width: 2.5; stroke-dasharray: 5 4; }
svg .lenmk { fill: var(--bg); stroke: var(--text); stroke-width: 2; }
svg .ln0 { stroke: var(--s0); } svg .ln1 { stroke: var(--s1); } svg .ln2 { stroke: var(--s2); } svg .ln3 { stroke: var(--s3); }
svg .f0 { fill: var(--s0); } svg .f1 { fill: var(--s1); } svg .f2 { fill: var(--s2); } svg .f3 { fill: var(--s3); }
svg .crv { fill: none; stroke-width: 2.2; }
svg .frame { fill: none; stroke: var(--border); stroke-width: 1; }
svg .diag { stroke: var(--muted); stroke-width: 1.2; stroke-dasharray: 4 4; }
table.mg { font-size: 26px; } table.mg th { font-size: 18px; } table.mg td, table.mg th { padding: 12px 14px; }
table.mg td.n { font-weight: 650; }
table.mg tr.refrow td { background: var(--surface); color: var(--muted); font-weight: 400; border-top: 2px solid var(--border); }
table.sm { font-size: 17px; } table.sm th { font-size: 15px; } table.sm td, table.sm th { padding: 5px 8px; }
table.md { font-size: 18px; } table.md th { font-size: 15px; } table.md td, table.md th { padding: 7px 9px; line-height: 1.3; }
table.md td:first-child { font-weight: 650; white-space: nowrap; }
table.md3 { font-size: 16.5px; } table.md3 td, table.md3 th { padding: 6px 8px; white-space: nowrap; } table.md3 code { font-size: 15px; }
.sw { display: inline-block; width: 13px; height: 13px; border-radius: 3px; vertical-align: -1px; margin-right: 6px; }
.sw.oc { background: var(--oc); } .sw.ul { background: var(--ul); } .sw.sup { background: var(--sup); }
ul.short { font-size: 23px; line-height: 1.4; padding-left: 28px; } ul.short li { margin-bottom: 12px; }
ul.tight { font-size: 19px; line-height: 1.38; padding-left: 24px; } ul.tight li { margin-bottom: 7px; }
.legend { font-size: 16px; color: var(--muted); display: flex; gap: 18px; flex-wrap: wrap; align-items: center; margin: 0 0 4px; }
.legend svg { vertical-align: -3px; }

:root { --mae: #0f8b8d; --mae2: #7cc7c4; }
@media (prefers-color-scheme: dark) { :root:not([data-theme="light"]) { --mae: #4fd1d3; --mae2: #2b6f70; } }
:root[data-theme="dark"] { --mae: #4fd1d3; --mae2: #2b6f70; }
svg .c-mae { fill: var(--mae); } svg .c-mae2 { fill: var(--mae2); } svg .l-mae { stroke: var(--mae); }
svg .ring-mae { fill: var(--bg); stroke: var(--mae); stroke-width: 3; }
.sw.mae { background: var(--mae); } .sw.mae2 { background: var(--mae2); } .sw.mah { background: var(--bar-u); }
table.mae-t { font-size: 18px; } table.mae-t th { font-size: 14.5px; } table.mae-t td, table.mae-t th { padding: 6px 8px; }
table.mg tr.maerow td { border-top: 2px dashed var(--border); font-size: 22px; color: var(--muted); }
table.mg tr.maerow td:first-child { color: var(--text); }

